@Override
public long skip(long n) throws IOException {
    if (n <= 0) {
        return 0;
    }
    // We need to actually read the bytes to cache them
    long skipped = 0;
    byte[] buffer = new byte[4096];
    while (skipped < n) {
        int toRead = (int) Math.min(buffer.length, n - skipped);
        int read = read(buffer, 0, toRead);
        if (read == -1) {
            break;
        }
        skipped += read;
    }
    return skipped;
}
